{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Measure BB Annual General Adjustment cap","requirement":"The Annual General Adjustment (AGA) that caps annual rent increases for fully covered units is limited to a maximum of 5%. Landlords may petition for rent increases only for completed capital improvements, not planned ones.","key_value":"5% maximum AGA","coverage_conditions":"Fully covered units, including most multifamily properties built before 1980 and government-owned or -subsidized units designated fully covered. Partially covered units are not subject to the rent ceiling.","applicability":{"built_on_or_before":"1980","built_after":null,"date_basis":"certificate_of_occupancy","min_units":null,"max_units":null,"owner_dependent":true,"other":"Government-subsidized units now covered"},"exemptions":"Units where tenant shares kitchen or bath with landlord are exempt only if landlord lived on the property at the start of the tenancy. Partially covered units are not subject to the rent ceiling.","penalty":null,"effective_date":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"The maximum AGA is 5%. This means that, if the formula in the Rent Ordinance results in an AGA that is greater than 5%, the AGA approved by the Board for that year can be no more than 5%.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Measure BB just cause eviction changes","requirement":"Covered-unit tenants may be evicted only for just cause; nonpayment eviction only if debt ≥ one month's Fair Market Rent; no eviction for refusing to sign a new lease or harmless breaches; eviction notices filed within 3 business days; owner move-in relocation aid adjusted annually.","key_value":"1 month FMR nonpayment threshold; 3 business days to file eviction notices","coverage_conditions":"Tenants in units fully or partially covered by the Rent Ordinance, including government-subsidized units. Shared kitchen/bath units exempt only if landlord lived on the property at the start of the tenancy.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Applies to fully and partially covered units"},"exemptions":"Units where tenant shares kitchen or bath with landlord are exempt only if landlord lived on the property at the start of the tenancy.","penalty":null,"effective_date":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"Eviction for nonpayment of rent is no longer allowed for rental debt less than one month of the Fair Market Rent for the unit","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
